def NURBS_2D(xi_1, xi_2, i_1, i_2, p_1, p_2, n_1, n_2, Xi_1, Xi_2, w):
    def NURBS_basis(xi, i, p, Xi, w):
        if p == 0:
            return np.array([t >= Xi[xi] and t < Xi[xi+1]], dtype=float) * w[i]
        else:
            alpha = (t - Xi[xi]) / (Xi[xi+p] - Xi[xi]) if Xi[xi+p]!= Xi[xi] else 0.0
            beta = (Xi[xi+p+1] - t) / (Xi[xi+p+1] - Xi[xi+1]) if Xi[xi+1]!= Xi[xi+p+1] else 0.0
            return alpha * NURBS_basis(xi, i, p-1, Xi, w) + beta * NURBS_basis(xi, i+1, p-1, Xi, w)

    N_1 = NURBS_basis(xi_1, i_1, p_1, Xi_1, w)
    N_2 = NURBS_basis(xi_2, i_2, p_2, Xi_2, w)
    denominator = np.sum(N_1 * N_2 * w)
    N = (N_1 * N_2 * w) / denominator if denominator!= 0 else np.zeros_like(N_1)
    return N
