def D_l_analy(l1, l2, q, d, D0, bg_eps):
    N = len(D0)
    D_qz_qz_prime = np.zeros((N, N), dtype=complex)

    for qz in range(N):
        for qz_prime in range(N):
            D_qz_qz_prime[qz, qz_prime] = np.exp(-1j * q * qz * d) * np.exp(1j * q * qz_prime * d) * D0[qz, qz_prime]

    D_l = 0
    for qz in range(N):
        for qz_prime in range(N):
            D_l += np.exp(1j * q * l1 * d) * np.exp(-1j * q * l2 * d) * D_qz_qz_prime[qz, qz_prime]

    D_l /= N**2
    return D_l
